"""Exercices historiques du chapitre 9 (identifiants conservés), extraits
de exercises_bank_premiere.json le 2026-10-26 : (id, notion, niveau, énoncé,
réponse, indice, étapes). Réécrits par banque_ch09.py."""

HISTORIQUES = (
    (1710, 'Probabilité conditionnelle', 1, 'On donne $P(A) = \\dfrac{9}{20}$ et $P(A \\cap B) = \\dfrac{1}{4}$. Calculer la probabilité conditionnelle $P_A(B)$.', '$P_A(B) = \\dfrac{5}{9}$', 'Utiliser $P_A(B)=\\dfrac{P(A\\cap B)}{P(A)}$.', ('Étape 1 : On utilise $P_A(B) = \\dfrac{P(A\\cap B)}{P(A)}$.', 'Étape 2 : $P_A(B) = \\dfrac{\\dfrac{1}{4}}{\\dfrac{9}{20}} = \\dfrac{5}{9}$.')),
    (1712, 'Probabilité conditionnelle', 1, 'On donne $P(A) = \\dfrac{63}{100}$ et $P_A(B) = \\dfrac{77}{100}$. Calculer $P(A \\cap B)$.', '$P(A \\cap B) = \\dfrac{4851}{10000}$', 'Utiliser $P(A\\cap B)=P(A)\\times P_A(B)$.', ('Étape 1 : On utilise $P(A\\cap B) = P(A) \\times P_A(B)$.', 'Étape 2 : $P(A\\cap B) = \\dfrac{63}{100} \\times \\dfrac{77}{100} = \\dfrac{4851}{10000}$.')),
    (1768, 'Arbres pondérés', 1, "Dans un lycée avec deux filières, un événement $A$ vérifie $P(A) = \\dfrac{1}{2}$. On sait que $P_A(B) = \\dfrac{1}{4}$ et $P_{\\overline{A}}(B) = \\dfrac{11}{20}$. Construire l'arbre pondéré correspondant puis calculer $P(B)$.", '$P(B) = \\dfrac{2}{5}$', 'Utiliser la formule des probabilités totales : $P(B)=P(A)P_A(B)+P(\\overline{A})P_{\\overline{A}}(B)$.', ("Étape 1 : L'arbre a deux branches initiales : $P(A) = \\dfrac{1}{2}$ et $P(\\overline{A}) = 1-\\dfrac{1}{2} = \\dfrac{1}{2}$.", 'Étape 2 : Sur chaque branche, on place $P_A(B)=\\dfrac{1}{4}$, $P_A(\\overline{B})=\\dfrac{3}{4}$, $P_{\\overline{A}}(B)=\\dfrac{11}{20}$ et $P_{\\overline{A}}(\\overline{B})=\\dfrac{9}{20}$.', "Étape 3 : D'après la formule des probabilités totales, $P(B) = P(A)\\times P_A(B) + P(\\overline{A})\\times P_{\\overline{A}}(B)$.", 'Étape 4 : $P(B) = \\dfrac{1}{2}\\times\\dfrac{1}{4} + \\dfrac{1}{2}\\times\\dfrac{11}{20} = \\dfrac{2}{5}$.')),
    (1769, 'Arbres pondérés', 1, "Dans une loterie avec deux types de billets, un événement $A$ vérifie $P(A) = \\dfrac{3}{10}$. On sait que $P_A(B) = \\dfrac{3}{20}$ et $P_{\\overline{A}}(B) = \\dfrac{11}{20}$. Construire l'arbre pondéré correspondant puis calculer $P(B)$.", '$P(B) = \\dfrac{43}{100}$', 'Utiliser la formule des probabilités totales : $P(B)=P(A)P_A(B)+P(\\overline{A})P_{\\overline{A}}(B)$.', ("Étape 1 : L'arbre a deux branches initiales : $P(A) = \\dfrac{3}{10}$ et $P(\\overline{A}) = 1-\\dfrac{3}{10} = \\dfrac{7}{10}$.", 'Étape 2 : Sur chaque branche, on place $P_A(B)=\\dfrac{3}{20}$, $P_A(\\overline{B})=\\dfrac{17}{20}$, $P_{\\overline{A}}(B)=\\dfrac{11}{20}$ et $P_{\\overline{A}}(\\overline{B})=\\dfrac{9}{20}$.', "Étape 3 : D'après la formule des probabilités totales, $P(B) = P(A)\\times P_A(B) + P(\\overline{A})\\times P_{\\overline{A}}(B)$.", 'Étape 4 : $P(B) = \\dfrac{3}{10}\\times\\dfrac{3}{20} + \\dfrac{7}{10}\\times\\dfrac{11}{20} = \\dfrac{43}{100}$.')),
    (1772, 'Arbres pondérés', 1, "Dans une usine possédant deux machines, un événement $A$ vérifie $P(A) = \\dfrac{41}{50}$. On sait que $P_A(B) = \\dfrac{3}{100}$ et $P_{\\overline{A}}(B) = \\dfrac{11}{20}$. Construire l'arbre pondéré correspondant puis calculer $P(B)$.", '$P(B) = \\dfrac{309}{2500}$', 'Utiliser la formule des probabilités totales : $P(B)=P(A)P_A(B)+P(\\overline{A})P_{\\overline{A}}(B)$.', ("Étape 1 : L'arbre a deux branches initiales : $P(A) = \\dfrac{41}{50}$ et $P(\\overline{A}) = 1-\\dfrac{41}{50} = \\dfrac{9}{50}$.", 'Étape 2 : Sur chaque branche, on place $P_A(B)=\\dfrac{3}{100}$, $P_A(\\overline{B})=\\dfrac{97}{100}$, $P_{\\overline{A}}(B)=\\dfrac{11}{20}$ et $P_{\\overline{A}}(\\overline{B})=\\dfrac{9}{20}$.', "Étape 3 : D'après la formule des probabilités totales, $P(B) = P(A)\\times P_A(B) + P(\\overline{A})\\times P_{\\overline{A}}(B)$.", 'Étape 4 : $P(B) = \\dfrac{41}{50}\\times\\dfrac{3}{100} + \\dfrac{9}{50}\\times\\dfrac{11}{20} = \\dfrac{309}{2500}$.')),
    (1826, "Notion d'indépendance", 1, 'On donne $P(A) = \\dfrac{9}{20}$, $P(B) = \\dfrac{4}{5}$ et $P(A \\cap B) = \\dfrac{9}{25}$. Les événements $A$ et $B$ sont-ils indépendants ? Justifier.', 'Oui, $A$ et $B$ sont indépendants.', 'Comparer $P(A\\cap B)$ à $P(A)\\times P(B)$.', ('Étape 1 : $A$ et $B$ sont indépendants si, et seulement si, $P(A\\cap B) = P(A)\\times P(B)$.', 'Étape 2 : $P(A)\\times P(B) = \\dfrac{9}{20}\\times\\dfrac{4}{5} = \\dfrac{9}{25}$.', 'Étape 3 : Comme $P(A\\cap B) = \\dfrac{9}{25} = P(A)\\times P(B)$, $A$ et $B$ sont indépendants.')),
    (1829, "Notion d'indépendance", 1, 'On donne $P(B) = \\dfrac{7}{10}$ et $P_A(B) = \\dfrac{4}{5}$. Les événements $A$ et $B$ sont-ils indépendants ? Justifier.', 'Non, $A$ et $B$ ne sont pas indépendants.', "Comparer $P_A(B)$ à $P(B)$ : l'égalité caractérise l'indépendance.", ('Étape 1 : $A$ et $B$ sont indépendants si, et seulement si, $P_A(B) = P(B)$.', 'Étape 2 : Comme $P_A(B) = \\dfrac{4}{5} \\neq P(B) = \\dfrac{7}{10}$, les événements $A$ et $B$ ne sont pas indépendants.')),
    (2000, 'Probabilité conditionnelle', 1, 'On donne $P(B) = \\dfrac{1}{2}$ et $P(A \\cap B) = \\dfrac{1}{4}$. Calculer la probabilité conditionnelle $P_B(A)$.', '$P_B(A) = \\dfrac{1}{2}$', 'Utiliser $P_B(A)=\\dfrac{P(A\\cap B)}{P(B)}$.', ('Étape 1 : On utilise $P_B(A) = \\dfrac{P(A\\cap B)}{P(B)}$.', 'Étape 2 : $P_B(A) = \\dfrac{\\dfrac{1}{4}}{\\dfrac{1}{2}} = \\dfrac{1}{2}$.')),
    (2001, 'Probabilité conditionnelle', 1, 'On donne $P(B) = \\dfrac{3}{5}$ et $P(A \\cap B) = \\dfrac{3}{10}$. Calculer la probabilité conditionnelle $P_B(A)$.', '$P_B(A) = \\dfrac{1}{2}$', 'Utiliser $P_B(A)=\\dfrac{P(A\\cap B)}{P(B)}$.', ('Étape 1 : On utilise $P_B(A) = \\dfrac{P(A\\cap B)}{P(B)}$.', 'Étape 2 : $P_B(A) = \\dfrac{\\dfrac{3}{10}}{\\dfrac{3}{5}} = \\dfrac{1}{2}$.')),
    (2002, 'Probabilité conditionnelle', 4, "Dans une population, la proportion de personnes atteintes d'une maladie $M$ est $P(M) = \\dfrac{1}{100}$. Un test de dépistage est positif ($T$) pour $90\\%$ des personnes malades : $P_M(T) = \\dfrac{9}{10}$. Il est aussi positif, à tort, pour $5\\%$ des personnes non malades : $P_{\\overline{M}}(T) = \\dfrac{1}{20}$. Calculer $P(T)$ puis la probabilité $P_T(M)$ qu'une personne testée positive soit réellement malade.", '$P(T) = \\dfrac{117}{2000}$ et $P_T(M) = \\dfrac{2}{13}$', 'Calculer $P(T)$ avec la formule des probabilités totales, puis utiliser $P_T(M)=\\dfrac{P(M\\cap T)}{P(T)}$.', ('Étape 1 : $P(\\overline{M}) = 1 - \\dfrac{1}{100} = \\dfrac{99}{100}$.', "Étape 2 : D'après la formule des probabilités totales, $P(T) = P(M)\\times P_M(T) + P(\\overline{M})\\times P_{\\overline{M}}(T) = \\dfrac{1}{100}\\times\\dfrac{9}{10} + \\dfrac{99}{100}\\times\\dfrac{1}{20} = \\dfrac{117}{2000}$.", 'Étape 3 : $P(M\\cap T) = P(M)\\times P_M(T) = \\dfrac{1}{100}\\times\\dfrac{9}{10} = \\dfrac{9}{1000}$.', 'Étape 4 : $P_T(M) = \\dfrac{P(M\\cap T)}{P(T)} = \\dfrac{\\dfrac{9}{1000}}{\\dfrac{117}{2000}} = \\dfrac{2}{13}$.')),
    (2003, 'Probabilité conditionnelle', 4, "Dans une usine, la proportion de pièces défectueuses est $P(D) = \\dfrac{1}{20}$. Un contrôle automatique détecte (événement $A$) $80\\%$ des pièces défectueuses, soit $P_D(A) = \\dfrac{4}{5}$, et déclenche une fausse alerte pour $2\\%$ des pièces non défectueuses, soit $P_{\\overline{D}}(A) = \\dfrac{1}{50}$. Calculer $P(A)$ puis $P_A(D)$, la probabilité qu'une pièce signalée par le contrôle soit réellement défectueuse.", '$P(A) = \\dfrac{59}{1000}$ et $P_A(D) = \\dfrac{40}{59}$', 'Calculer $P(A)$ avec la formule des probabilités totales, puis utiliser $P_A(D)=\\dfrac{P(D\\cap A)}{P(A)}$.', ('Étape 1 : $P(\\overline{D}) = 1 - \\dfrac{1}{20} = \\dfrac{19}{20}$.', 'Étape 2 : $P(A) = P(D)\\times P_D(A) + P(\\overline{D})\\times P_{\\overline{D}}(A) = \\dfrac{1}{20}\\times\\dfrac{4}{5} + \\dfrac{19}{20}\\times\\dfrac{1}{50} = \\dfrac{59}{1000}$.', 'Étape 3 : $P(D\\cap A) = P(D)\\times P_D(A) = \\dfrac{1}{20}\\times\\dfrac{4}{5} = \\dfrac{1}{25}$.', 'Étape 4 : $P_A(D) = \\dfrac{P(D\\cap A)}{P(A)} = \\dfrac{\\dfrac{1}{25}}{\\dfrac{59}{1000}} = \\dfrac{40}{59}$.')),
    (2004, 'Probabilité conditionnelle', 3, "Lors d'une campagne de dépistage, un test a permis de calculer que $P_T(M) = \\dfrac{2}{13}$, où $T$ est l'événement « le test est positif » et $M$ l'événement « la personne est malade ». Interpréter ce résultat dans le contexte de l'énoncé, en une phrase.", 'Parmi les personnes testées positives, seule une sur $13$ environ (soit $\\dfrac{2}{13}\\approx 15,4\\%$) est réellement malade.', '$P_T(M)$ est une proportion parmi les personnes testées positives, pas parmi toute la population.', ('Étape 1 : $P_T(M)$ se lit « probabilité que la personne soit malade, sachant que son test est positif ».', 'Étape 2 : $\\dfrac{2}{13} \\approx 0,154$, donc environ $15,4\\%$ des personnes testées positives sont réellement malades.', "Étape 3 : Cela signifie qu'un test positif ne garantit pas d'être malade : la majorité des personnes testées positives (environ $84,6\\%$) ne le sont pas, à cause du grand nombre de faux positifs par rapport à la faible proportion de malades dans la population.")),
    (2005, 'Probabilité conditionnelle', 3, "Dans le contexte de l'exercice précédent sur le contrôle qualité industriel, on a trouvé $P_A(D) = \\dfrac{4}{23}$. Expliquer ce que signifie ce résultat pour le responsable de production.", 'Parmi les pièces signalées par le contrôle, seules $4$ sur $23$ environ sont réellement défectueuses : le contrôle produit beaucoup de fausses alertes.', 'Comparer $P_A(D)$ à $1$ : un résultat éloigné de $1$ traduit un contrôle peu fiable.', ("Étape 1 : $P_A(D)$ est la probabilité qu'une pièce soit défectueuse sachant qu'elle a été signalée par le contrôle.", 'Étape 2 : $\\dfrac{4}{23} \\approx 0,174$, donc environ $17,4\\%$ seulement des pièces signalées sont réellement défectueuses.', 'Étape 3 : Le responsable doit donc vérifier manuellement chaque pièce signalée avant de la rejeter, car la majorité des alertes sont fausses.')),
    (2006, 'Probabilité conditionnelle', 2, "Un lycée compte $200$ élèves : $120$ filles et $80$ garçons. Parmi les filles, $90$ pratiquent un sport en club ; parmi les garçons, $50$ pratiquent un sport en club. On choisit un élève au hasard. On note $F$ l'événement « l'élève est une fille » et $S$ l'événement « l'élève pratique un sport en club ». Calculer $P_F(S)$.", '$P_F(S) = \\dfrac{3}{4}$', 'Se ramener aux effectifs parmi les filles uniquement : $P_F(S) = \\dfrac{\\text{filles sportives}}{\\text{total filles}}$.', ("Étape 1 : $P_F(S)$ se calcule uniquement parmi la population des filles, sans utiliser l'effectif total de $200$.", 'Étape 2 : Parmi les $120$ filles, $90$ pratiquent un sport, donc $P_F(S) = \\dfrac{90}{120} = \\dfrac{3}{4}$.')),
    (2007, 'Probabilité conditionnelle', 3, "On reprend les données de l'exercice précédent : $200$ élèves, $120$ filles dont $90$ sportives, $80$ garçons dont $50$ sportifs. On choisit cette fois un élève au hasard parmi ceux qui pratiquent un sport en club. Calculer la probabilité $P_S(F)$ que cet élève soit une fille.", '$P_S(F) = \\dfrac{9}{14}$', 'Se ramener aux effectifs parmi les sportifs uniquement : ne pas confondre avec $P_F(S)$.', ('Étape 1 : Le nombre total de sportifs est $90 + 50 = 140$.', 'Étape 2 : Parmi eux, $90$ sont des filles, donc $P_S(F) = \\dfrac{90}{140} = \\dfrac{9}{14}$.', 'Étape 3 : On remarque que $P_S(F) \\neq P_F(S)$ : les deux probabilités conditionnelles ne coïncident pas en général.')),
    (2008, 'Probabilité conditionnelle', 2, 'On donne deux événements $A$ et $B$ tels que $P(A) = \\dfrac{2}{5}$ et $P(B) = \\dfrac{2}{5}$. Vrai ou faux : « $P_A(B) = P_B(A)$ » ? Justifier.', 'Vrai, car $P(A) = P(B)$.', 'Comparer les deux formules $P_A(B)=\\dfrac{P(A\\cap B)}{P(A)}$ et $P_B(A)=\\dfrac{P(A\\cap B)}{P(B)}$.', ('Étape 1 : $P_A(B) = \\dfrac{P(A\\cap B)}{P(A)}$ et $P_B(A) = \\dfrac{P(A\\cap B)}{P(B)}$ ont le même numérateur $P(A\\cap B)$.', 'Étape 2 : Ces deux quotients sont donc égaux si, et seulement si, leurs dénominateurs $P(A)$ et $P(B)$ sont égaux.', "Étape 3 : Comme $P(A) = P(B) = \\dfrac{2}{5}$, on a bien $P_A(B) = P_B(A)$ : l'affirmation est vraie.")),
    (2009, 'Probabilité conditionnelle', 2, 'On donne $P(A) = \\dfrac{3}{10}$ et $P(B) = \\dfrac{7}{10}$, avec $P(A\\cap B) = \\dfrac{1}{5}$. Vrai ou faux : « $P_A(B) = P_B(A)$ » ? Justifier par le calcul.', 'Faux, car $P_A(B) = \\dfrac{2}{3}$ alors que $P_B(A) = \\dfrac{2}{7}$.', 'Calculer séparément $P_A(B)$ et $P_B(A)$ puis comparer.', ('Étape 1 : $P_A(B) = \\dfrac{P(A\\cap B)}{P(A)} = \\dfrac{\\frac{1}{5}}{\\frac{3}{10}} = \\dfrac{2}{3}$.', 'Étape 2 : $P_B(A) = \\dfrac{P(A\\cap B)}{P(B)} = \\dfrac{\\frac{1}{5}}{\\frac{7}{10}} = \\dfrac{2}{7}$.', "Étape 3 : Comme $\\dfrac{2}{3} \\neq \\dfrac{2}{7}$, l'affirmation est fausse : $P_A(B)$ et $P_B(A)$ ne sont égales que dans des cas particuliers (par exemple $P(A)=P(B)$).")),
    (2010, 'Probabilité conditionnelle', 2, "Un élève doit calculer $P_A(B)$ sachant $P(A) = \\dfrac{1}{4}$ et $P(A\\cap B) = \\dfrac{1}{10}$. Il écrit : « $P_A(B) = \\dfrac{P(A\\cap B)}{P(B)}$ », puis reste bloqué car $P(B)$ n'est pas donné. Identifier son erreur et donner le bon calcul de $P_A(B)$.", "$P_A(B) = \\dfrac{2}{5}$ (l'élève a divisé par $P(B)$ au lieu de $P(A)$).", "La formule correcte est $P_A(B) = \\dfrac{P(A\\cap B)}{P(A)}$ : on divise toujours par la probabilité de l'événement qui conditionne.", ("Étape 1 : L'erreur de l'élève est d'avoir divisé par $P(B)$ au lieu de $P(A)$ : la formule correcte est $P_A(B) = \\dfrac{P(A\\cap B)}{P(A)}$, où $A$ est l'événement de conditionnement (celui qui est déjà réalisé).", 'Étape 2 : Avec les bonnes données, $P_A(B) = \\dfrac{\\frac{1}{10}}{\\frac{1}{4}} = \\dfrac{2}{5}$.', "Étape 3 : Il n'était donc pas nécessaire de connaître $P(B)$ pour calculer $P_A(B)$.")),
    (2011, 'Probabilité conditionnelle', 3, "On donne $P(A) = \\dfrac{2}{5}$, $P(B) = \\dfrac{1}{2}$ et $P_A(B) = \\dfrac{3}{4}$. Pour calculer $P(A \\cap B)$, un élève écrit : « $A$ et $B$ sont indépendants donc $P(A\\cap B) = P(A) \\times P(B) = \\dfrac{2}{5}\\times\\dfrac{1}{2} = \\dfrac{1}{5}$ ». Identifier l'erreur de raisonnement et donner le calcul correct.", "$P(A \\cap B) = \\dfrac{3}{10}$ (et non $\\dfrac{1}{5}$ : rien n'indique que $A$ et $B$ sont indépendants).", "Rien dans l'énoncé n'affirme l'indépendance : la formule générale est $P(A\\cap B) = P(A)\\times P_A(B)$, à utiliser dès que $P_A(B)$ est connue.", ("Étape 1 : L'élève suppose à tort que $A$ et $B$ sont indépendants. Or $P_A(B) = \\dfrac{3}{4} \\neq P(B) = \\dfrac{1}{2}$, donc $A$ et $B$ ne sont pas indépendants.", 'Étape 2 : La formule générale, valable dans tous les cas, est $P(A\\cap B) = P(A) \\times P_A(B)$ (et non $P(A)\\times P(B)$, réservée au cas indépendant).', "Étape 3 : $P(A\\cap B) = \\dfrac{2}{5}\\times\\dfrac{3}{4} = \\dfrac{3}{10}$, ce qui est différent du résultat erroné $\\dfrac{1}{5}$ obtenu par l'élève.")),
    (2012, 'Probabilité conditionnelle', 3, "Une étude sur $1000$ personnes donne le tableau suivant : sur les $20$ personnes malades, $18$ sont testées positives et $2$ négatives ; sur les $980$ personnes non malades, $49$ sont testées positives (faux positifs) et $931$ négatives. On choisit une personne au hasard parmi les $1000$. Calculer la probabilité qu'une personne testée positive soit réellement malade.", '$P_T(M) = \\dfrac{18}{67}$', 'Se ramener au sous-groupe des personnes testées positives : $18$ malades sur un total de $18+49$ testés positifs.', ('Étape 1 : Le nombre total de personnes testées positives est $18 + 49 = 67$.', 'Étape 2 : Parmi elles, $18$ sont réellement malades, donc $P_T(M) = \\dfrac{18}{67} = \\dfrac{18}{67}$.', "Étape 3 : Cela signifie qu'un peu moins d'un tiers ($\\dfrac{18}{67} \\approx 0,269$) des personnes testées positives sont réellement malades.")),
    (2013, 'Probabilité conditionnelle', 2, "Lors d'un sondage auprès de $500$ personnes ($300$ habitant en zone urbaine et $200$ en zone rurale), $210$ des habitants urbains se déclarent favorables à un projet, contre $70$ des habitants ruraux. On choisit une personne au hasard parmi les habitants urbains. Calculer la probabilité qu'elle soit favorable au projet.", '$P_U(F) = \\dfrac{7}{10}$', "Se ramener à l'effectif des urbains uniquement.", ('Étape 1 : Parmi les $300$ habitants urbains, $210$ sont favorables.', 'Étape 2 : $P_U(F) = \\dfrac{210}{300} = \\dfrac{7}{10}$.')),
    (2014, 'Probabilité conditionnelle', 3, 'Dans une usine, la proportion de pièces défectueuses est $P(D) = \\dfrac{1}{10}$. On installe un capteur qui déclenche une alerte (événement $C$) pour $90\\%$ des pièces défectueuses : $P_D(C) = \\dfrac{9}{10}$. Comparer $P_D(C)$ et $P(C)$ sachant que $P(C) = \\dfrac{1}{10}$, puis conclure sur la pertinence du capteur.', "Le capteur est pertinent, car $P_D(C) = \\dfrac{9}{10} \\neq P(C) = \\dfrac{1}{10}$ : savoir qu'une pièce est défectueuse change fortement la probabilité qu'elle déclenche l'alerte.", "Si $P_D(C) = P(C)$, l'information « pièce défectueuse » n'apporte rien sur $C$ ; plus l'écart est grand, plus le test est informatif.", ('Étape 1 : $P_D(C) = \\dfrac{9}{10}$ alors que $P(C) = \\dfrac{1}{10}$ : les deux valeurs sont très différentes.', "Étape 2 : Si $D$ et $C$ étaient indépendants, on aurait $P_D(C) = P(C)$, ce qui n'est pas le cas ici.", "Étape 3 : Connaître le fait qu'une pièce est défectueuse multiplie par $9$ la probabilité que le capteur déclenche une alerte : le capteur apporte donc une information utile, il est pertinent.")),
    (2015, 'Probabilité conditionnelle', 2, "Deux tests de dépistage $T_1$ et $T_2$ sont proposés pour une même maladie $M$. Le test $T_1$ a une sensibilité $P_M(T_1) = \\dfrac{7}{10}$ et le test $T_2$ a une sensibilité $P_M(T_2) = \\dfrac{4}{5}$. Sachant que la sensibilité mesure la probabilité qu'un malade soit détecté par le test, quel test choisir pour minimiser le risque de ne pas détecter un malade ? Justifier.", 'Choisir $T_2$, car $P_M(T_2) = \\dfrac{4}{5} > P_M(T_1) = \\dfrac{7}{10}$ : il détecte une plus grande proportion de malades.', 'Comparer directement les deux probabilités conditionnelles $P_M(T_1)$ et $P_M(T_2)$ : la plus grande correspond au test le plus fiable pour détecter les malades.', ('Étape 1 : On met les deux sensibilités au même dénominateur : $P_M(T_1) = \\dfrac{7}{10} = \\dfrac{14}{20}$ et $P_M(T_2) = \\dfrac{4}{5} = \\dfrac{16}{20}$.', 'Étape 2 : Comme $\\dfrac{16}{20} > \\dfrac{14}{20}$, on a $P_M(T_2) > P_M(T_1)$.', 'Étape 3 : Le test $T_2$ détecte une plus grande proportion de malades ; il minimise donc le risque de faux négatif (malade non détecté).')),
    (2016, 'Probabilité conditionnelle', 5, "Une compagnie d'assurance estime que la probabilité qu'un contrat donne lieu à un sinistre ($S$) dans l'année est $P(S) = \\dfrac{1}{25}$. Un algorithme de détection signale (événement $Z$) $90\\%$ des contrats qui donneront lieu à un sinistre : $P_S(Z) = \\dfrac{9}{10}$. Il signale aussi, à tort, $2\\%$ des contrats sans sinistre : $P_{\\overline{S}}(Z) = \\dfrac{1}{50}$. 1) Calculer $P(Z)$. 2) Calculer $P_Z(S)$. 3) Interpréter ce dernier résultat et le comparer à $P(S)$ pour juger de l'utilité de l'algorithme.", "$P(Z) = \\dfrac{69}{1250}$, $P_Z(S) = \\dfrac{15}{23}$ ; comme $P_Z(S) > P(S)$, l'algorithme est utile.", 'Utiliser la formule des probabilités totales pour $P(Z)$, puis $P_Z(S) = \\dfrac{P(S\\cap Z)}{P(Z)}$, et comparer à $P(S)$.', ('Étape 1 : $P(\\overline{S}) = 1 - \\dfrac{1}{25} = \\dfrac{24}{25}$.', 'Étape 2 : $P(Z) = P(S)\\times P_S(Z) + P(\\overline{S})\\times P_{\\overline{S}}(Z) = \\dfrac{1}{25}\\times\\dfrac{9}{10} + \\dfrac{24}{25}\\times\\dfrac{1}{50} = \\dfrac{69}{1250}$.', 'Étape 3 : $P(S\\cap Z) = P(S)\\times P_S(Z) = \\dfrac{1}{25}\\times\\dfrac{9}{10} = \\dfrac{9}{250}$, donc $P_Z(S) = \\dfrac{\\dfrac{9}{250}}{\\dfrac{69}{1250}} = \\dfrac{15}{23}$.', "Étape 4 : Comme $P_Z(S) = \\dfrac{15}{23} \\approx 0,529$ est bien supérieur à $P(S) = \\dfrac{1}{25} = 0,04$, un contrat signalé par l'algorithme a une probabilité de sinistre beaucoup plus élevée que la moyenne : l'algorithme est donc utile pour cibler les contrats à risque.")),
    (2017, 'Probabilité conditionnelle', 5, "Une entreprise interroge $400$ clients : $250$ sont fidélisés ($F$) et $150$ ne le sont pas. Parmi les clients fidélisés, $200$ se disent satisfaits ($Sa$) ; parmi les non fidélisés, $60$ se disent satisfaits. 1) Calculer $P_F(Sa)$. 2) Calculer $P_{\\overline{F}}(Sa)$. 3) Calculer $P_{Sa}(F)$, puis comparer ce dernier résultat à la proportion de clients fidélisés dans l'échantillon total ($\\dfrac{250}{400}$) et conclure sur le lien entre fidélisation et satisfaction.", '$P_F(Sa) = \\dfrac{4}{5}$, $P_{\\overline{F}}(Sa) = \\dfrac{2}{5}$, $P_{Sa}(F) = \\dfrac{10}{13}$ ; comme $P_{Sa}(F) > \\dfrac{250}{400} = \\dfrac{5}{8}$, les clients satisfaits sont surreprésentés parmi les fidélisés.', 'Calculer chaque probabilité conditionnelle en se ramenant au sous-groupe concerné, puis comparer à la proportion globale de fidélisés.', ('Étape 1 : $P_F(Sa) = \\dfrac{200}{250} = \\dfrac{4}{5}$.', 'Étape 2 : $P_{\\overline{F}}(Sa) = \\dfrac{60}{150} = \\dfrac{2}{5}$.', 'Étape 3 : Le nombre total de clients satisfaits est $200+60=260$, donc $P_{Sa}(F) = \\dfrac{200}{260} = \\dfrac{10}{13}$.', "Étape 4 : La proportion de fidélisés dans l'échantillon total est $\\dfrac{250}{400} = \\dfrac{5}{8} = 0,625$. Comme $P_{Sa}(F) = \\dfrac{10}{13} \\approx 0,769 > 0,625$, les clients satisfaits sont proportionnellement plus souvent fidélisés que dans l'ensemble de la clientèle : la satisfaction semble liée à la fidélisation.")),
    (2018, 'Probabilité conditionnelle', 1, 'On donne $P(A) = \\dfrac{5}{8}$ et $P(A \\cap B) = \\dfrac{1}{4}$. Calculer la probabilité conditionnelle $P_A(B)$.', '$P_A(B) = \\dfrac{2}{5}$', 'Utiliser $P_A(B)=\\dfrac{P(A\\cap B)}{P(A)}$.', ('Étape 1 : On utilise $P_A(B) = \\dfrac{P(A\\cap B)}{P(A)}$.', 'Étape 2 : $P_A(B) = \\dfrac{\\dfrac{1}{4}}{\\dfrac{5}{8}} = \\dfrac{2}{5}$.')),
    (2019, 'Probabilité conditionnelle', 2, "Dans une classe de $300$ élèves, $150$ préfèrent les mathématiques et $150$ le français. Parmi les élèves qui préfèrent les mathématiques, $90$ sont des filles ; parmi ceux qui préfèrent le français, $60$ sont des filles. On choisit un élève au hasard parmi les filles de la classe. Calculer la probabilité qu'elle préfère les mathématiques.", '$P_{\\text{Fille}}(\\text{Maths}) = \\dfrac{3}{5}$', "Il faut d'abord déterminer le nombre total de filles, puis se ramener à ce sous-groupe.", ('Étape 1 : Le nombre total de filles est $90 + 60 = 150$.', 'Étape 2 : Parmi elles, $90$ préfèrent les mathématiques, donc $P_{\\text{Fille}}(\\text{Maths}) = \\dfrac{90}{150} = \\dfrac{3}{5}$.')),
    (2020, "Notion d'indépendance", 1, 'On donne $P(A) = \\dfrac{3}{10}$ et $P_B(A) = \\dfrac{3}{10}$. Les événements $A$ et $B$ sont-ils indépendants ? Justifier.', 'Oui, $A$ et $B$ sont indépendants.', "Comparer $P_B(A)$ à $P(A)$ : l'égalité caractérise l'indépendance.", ('Étape 1 : $A$ et $B$ sont indépendants si, et seulement si, $P_B(A) = P(A)$.', 'Étape 2 : Comme $P_B(A) = \\dfrac{3}{10} = P(A)$, les événements $A$ et $B$ sont indépendants.')),
    (2021, "Notion d'indépendance", 1, 'On donne $P(A) = \\dfrac{2}{5}$ et $P_B(A) = \\dfrac{9}{20}$. Les événements $A$ et $B$ sont-ils indépendants ? Justifier.', 'Non, $A$ et $B$ ne sont pas indépendants.', "Comparer $P_B(A)$ à $P(A)$ : l'égalité caractérise l'indépendance.", ('Étape 1 : $A$ et $B$ sont indépendants si, et seulement si, $P_B(A) = P(A)$.', 'Étape 2 : Comme $P_B(A) = \\dfrac{9}{20} \\neq P(A) = \\dfrac{2}{5} = \\dfrac{8}{20}$, les événements $A$ et $B$ ne sont pas indépendants.')),
    (2022, "Notion d'indépendance", 3, "Un événement $A$ vérifie $P(A) = \\dfrac{2}{5}$, avec $P_A(B) = \\dfrac{3}{10}$ et $P_{\\overline{A}}(B) = \\dfrac{3}{10}$. Calculer $P(B)$ à l'aide de la formule des probabilités totales, puis déterminer si $A$ et $B$ sont indépendants.", '$P(B) = \\dfrac{3}{10}$ ; $A$ et $B$ sont indépendants car $P(B) = P_A(B)$.', 'Calculer $P(B)$ avec la formule des probabilités totales, puis comparer à $P_A(B)$.', ('Étape 1 : $P(\\overline{A}) = 1 - \\dfrac{2}{5} = \\dfrac{3}{5}$.', 'Étape 2 : $P(B) = P(A)\\times P_A(B) + P(\\overline{A})\\times P_{\\overline{A}}(B) = \\dfrac{2}{5}\\times\\dfrac{3}{10} + \\dfrac{3}{5}\\times\\dfrac{3}{10} = \\dfrac{3}{10}$.', "Étape 3 : Comme $P_A(B) = P_{\\overline{A}}(B) = \\dfrac{3}{10} = P(B)$, l'information « $A$ réalisé » ne change pas la probabilité de $B$ : $A$ et $B$ sont indépendants.")),
    (2023, "Notion d'indépendance", 3, "Un événement $A$ vérifie $P(A) = \\dfrac{1}{4}$, avec $P_A(B) = \\dfrac{1}{2}$ et $P_{\\overline{A}}(B) = \\dfrac{1}{5}$. Calculer $P(B)$ à l'aide de la formule des probabilités totales, puis déterminer si $A$ et $B$ sont indépendants.", '$P(B) = \\dfrac{11}{40}$ ; $A$ et $B$ ne sont pas indépendants car $P(B) \\neq P_A(B)$.', 'Calculer $P(B)$ avec la formule des probabilités totales, puis comparer à $P_A(B)$.', ('Étape 1 : $P(\\overline{A}) = 1 - \\dfrac{1}{4} = \\dfrac{3}{4}$.', 'Étape 2 : $P(B) = P(A)\\times P_A(B) + P(\\overline{A})\\times P_{\\overline{A}}(B) = \\dfrac{1}{4}\\times\\dfrac{1}{2} + \\dfrac{3}{4}\\times\\dfrac{1}{5} = \\dfrac{11}{40}$.', 'Étape 3 : Comme $P(B) = \\dfrac{11}{40} \\neq P_A(B) = \\dfrac{1}{2}$, les événements $A$ et $B$ ne sont pas indépendants.')),
    (2024, "Notion d'indépendance", 2, 'On tire une carte dans un jeu de $32$ cartes, on note sa couleur, on la remet dans le jeu, on mélange puis on tire une seconde carte. On note $A$ « la première carte est un cœur » et $B$ « la seconde carte est un cœur ». Expliquer, sans calcul, pourquoi $A$ et $B$ sont des événements indépendants.', 'Parce que la carte est remise avant le second tirage, le résultat du premier tirage ne modifie pas la composition du jeu pour le second : $P_A(B) = P(B)$.', "L'indépendance de deux tirages successifs est liée au fait que le premier ne change pas les conditions du second.", ('Étape 1 : Après le premier tirage, la carte est remise dans le jeu : la composition du jeu de $32$ cartes est donc identique avant le second tirage, que la première carte tirée ait été un cœur ou non.', 'Étape 2 : Ainsi $P_A(B) = P(B) = \\dfrac{8}{32} = \\dfrac{1}{4}$ : savoir que $A$ est réalisé ne change pas la probabilité de $B$.', 'Étape 3 : Par définition, $A$ et $B$ sont donc indépendants.')),
    (2025, "Notion d'indépendance", 2, 'On tire une carte dans un jeu de $32$ cartes, on note sa couleur, on ne la remet PAS dans le jeu, puis on tire une seconde carte parmi les $31$ restantes. On note $A$ « la première carte est un cœur » et $B$ « la seconde carte est un cœur ». Expliquer, sans calcul, pourquoi $A$ et $B$ ne sont pas indépendants.', "Parce que la carte n'est pas remise, la composition du jeu pour le second tirage dépend du résultat du premier : $P_A(B) \\neq P(B)$.", 'Comparer la composition du jeu restant selon que la première carte était un cœur ou non.', ('Étape 1 : Si la première carte est un cœur (événement $A$), il ne reste que $7$ cœurs parmi les $31$ cartes restantes : $P_A(B) = \\dfrac{7}{31}$.', "Étape 2 : Si la première carte n'est pas un cœur, il reste $8$ cœurs parmi les $31$ cartes restantes : $P_{\\overline{A}}(B) = \\dfrac{8}{31}$.", 'Étape 3 : Comme $P_A(B) \\neq P_{\\overline{A}}(B)$, la réalisation de $A$ modifie la probabilité de $B$ : $A$ et $B$ ne sont pas indépendants.')),
    (2026, "Notion d'indépendance", 3, 'Une boutique compte $240$ clients : $144$ hommes et $96$ femmes. Parmi les hommes, $60$ achètent un produit $P$ ; parmi les femmes, $40$ achètent ce même produit. On choisit un client au hasard. Notant $H$ « le client est un homme » et $A$ « le client achète le produit $P$ », déterminer si $H$ et $A$ sont indépendants.', 'Oui, $H$ et $A$ sont indépendants, car $P_H(A) = P(A) = \\dfrac{5}{12}$.', 'Calculer $P_H(A)$ et $P(A)$ à partir des effectifs, puis comparer.', ('Étape 1 : $P_H(A) = \\dfrac{60}{144} = \\dfrac{5}{12}$.', 'Étape 2 : $P(A) = \\dfrac{60+40}{240} = \\dfrac{100}{240} = \\dfrac{5}{12}$.', "Étape 3 : Comme $P_H(A) = P(A) = \\dfrac{5}{12}$, les événements $H$ et $A$ sont indépendants : le fait d'être un homme ne modifie pas la probabilité d'acheter le produit.")),
    (2027, "Notion d'indépendance", 3, 'Une étude porte sur $150$ patients : $90$ fumeurs et $60$ non-fumeurs. Parmi les fumeurs, $54$ développent une maladie $M$ ; parmi les non-fumeurs, $12$ développent cette maladie. On choisit un patient au hasard. Notant $F$ « le patient est fumeur » et $M$ « le patient est malade », déterminer si $F$ et $M$ sont indépendants.', 'Non, $F$ et $M$ ne sont pas indépendants, car $P_F(M) = \\dfrac{3}{5} \\neq P(M) = \\dfrac{11}{25}$.', 'Calculer $P_F(M)$ et $P(M)$ à partir des effectifs, puis comparer.', ('Étape 1 : $P_F(M) = \\dfrac{54}{90} = \\dfrac{3}{5}$.', 'Étape 2 : $P(M) = \\dfrac{54+12}{150} = \\dfrac{66}{150} = \\dfrac{11}{25}$.', 'Étape 3 : Comme $P_F(M) = \\dfrac{3}{5} \\neq P(M) = \\dfrac{11}{25}$, les événements $F$ et $M$ ne sont pas indépendants : être fumeur est associé à une probabilité plus élevée de développer la maladie.')),
    (2028, "Notion d'indépendance", 3, "Vrai ou faux : « Si $A$ et $B$ sont des événements incompatibles (c'est-à-dire $P(A\\cap B) = 0$) avec $P(A) = \\dfrac{1}{3}$ et $P(B) = \\dfrac{1}{4}$, alors $A$ et $B$ sont indépendants. » Justifier par le calcul.", 'Faux : $P(A\\cap B) = 0 \\neq P(A)\\times P(B) = \\dfrac{1}{12}$.', 'Comparer $P(A\\cap B)$ (donné) à $P(A)\\times P(B)$ : ne pas confondre incompatibilité et indépendance.', ('Étape 1 : $A$ et $B$ sont indépendants si, et seulement si, $P(A\\cap B) = P(A)\\times P(B)$.', 'Étape 2 : $P(A)\\times P(B) = \\dfrac{1}{3}\\times\\dfrac{1}{4} = \\dfrac{1}{12}$.', "Étape 3 : Comme $A$ et $B$ sont incompatibles, $P(A\\cap B) = 0 \\neq \\dfrac{1}{12}$ : $A$ et $B$ ne sont pas indépendants. L'affirmation est fausse : deux événements incompatibles de probabilités non nulles ne sont jamais indépendants.")),
    (2029, "Notion d'indépendance", 3, 'Vrai ou faux : « Un événement $A$ tel que $P(A) = \\dfrac{2}{5}$ (avec $0 < P(A) < 1$) est toujours indépendant de son événement contraire $\\overline{A}$. » Justifier par le calcul.', 'Faux : $P(A \\cap \\overline{A}) = 0 \\neq P(A)\\times P(\\overline{A}) = \\dfrac{6}{25}$.', '$A$ et $\\overline{A}$ sont incompatibles ($A \\cap \\overline{A} = \\emptyset$) : utiliser ce fait pour comparer à $P(A)\\times P(\\overline{A})$.', ('Étape 1 : $A$ et $\\overline{A}$ étant incompatibles, $P(A\\cap\\overline{A}) = 0$.', 'Étape 2 : $P(A)\\times P(\\overline{A}) = \\dfrac{2}{5}\\times\\dfrac{3}{5} = \\dfrac{6}{25}$, qui est non nul puisque $0 < P(A) < 1$.', "Étape 3 : Comme $P(A\\cap\\overline{A}) = 0 \\neq \\dfrac{6}{25} = P(A)\\times P(\\overline{A})$, $A$ et $\\overline{A}$ ne sont pas indépendants : l'affirmation est fausse (sauf cas limite $P(A)=0$ ou $P(A)=1$, exclu ici).")),
    (2030, "Notion d'indépendance", 2, 'Deux événements indépendants $A$ et $B$ vérifient $P(A) = \\dfrac{1}{3}$ et $P(B) = \\dfrac{1}{4}$. Un élève écrit : « $P(A\\cap B) = P(A) + P(B) = \\dfrac{1}{3}+\\dfrac{1}{4} = \\dfrac{7}{12}$ ». Identifier son erreur et donner le bon calcul de $P(A\\cap B)$.', '$P(A\\cap B) = \\dfrac{1}{12}$ (et non $\\dfrac{7}{12}$) : pour des événements indépendants, on multiplie les probabilités, on ne les additionne pas.', 'Pour deux événements indépendants, $P(A\\cap B) = P(A)\\times P(B)$, jamais $P(A)+P(B)$ (qui sert à $P(A\\cup B)$ pour des événements incompatibles).', ("Étape 1 : L'élève confond la formule de l'indépendance avec celle des événements incompatibles ($P(A\\cup B) = P(A)+P(B)$).", 'Étape 2 : Pour des événements indépendants, la formule correcte est $P(A\\cap B) = P(A)\\times P(B) = \\dfrac{1}{3}\\times\\dfrac{1}{4} = \\dfrac{1}{12}$.', 'Étape 3 : Le résultat correct $\\dfrac{1}{12}$ est bien inférieur au résultat erroné $\\dfrac{7}{12}$, ce qui est cohérent car $P(A\\cap B)$ doit être inférieur à la fois à $P(A)$ et $P(B)$.')),
    (2031, "Notion d'indépendance", 3, 'On donne $P(A) = \\dfrac{3}{5}$, $P(B) = \\dfrac{1}{2}$ et $P(A\\cap B) = \\dfrac{3}{10}$. Un élève affirme : « $P(A)\\times P(B) = \\dfrac{3}{5}\\times\\dfrac{1}{2} = \\dfrac{3}{7}$, donc comme $P(A\\cap B) = \\dfrac{3}{10} \\neq \\dfrac{3}{7}$, $A$ et $B$ ne sont pas indépendants. » Vérifier son calcul intermédiaire et corriger si besoin sa conclusion.', "L'élève a fait une erreur de calcul : $P(A)\\times P(B) = \\dfrac{3}{10}$ (et non $\\dfrac{3}{7}$), ce qui est égal à $P(A\\cap B)$ : $A$ et $B$ sont en réalité indépendants.", 'Recalculer $\\dfrac{3}{5}\\times\\dfrac{1}{2}$ : multiplier numérateurs entre eux et dénominateurs entre eux.', ("Étape 1 : $\\dfrac{3}{5}\\times\\dfrac{1}{2} = \\dfrac{3\\times1}{5\\times2} = \\dfrac{3}{10}$ : l'élève a fait une erreur de calcul en écrivant $\\dfrac{3}{7}$ (probablement en additionnant les dénominateurs au lieu de les multiplier).", 'Étape 2 : Le bon produit est $P(A)\\times P(B) = \\dfrac{3}{10}$.', "Étape 3 : Comme $P(A\\cap B) = \\dfrac{3}{10} = P(A)\\times P(B)$, les événements $A$ et $B$ sont en réalité indépendants : la conclusion de l'élève était fausse à cause de son erreur de calcul.")),
    (2032, "Notion d'indépendance", 2, 'Dans un atelier, deux machines $M_1$ et $M_2$ fonctionnent de façon indépendante. La probabilité que $M_1$ tombe en panne dans la journée est $\\dfrac{1}{20}$, celle que $M_2$ tombe en panne est $\\dfrac{1}{25}$. Calculer la probabilité que les deux machines tombent en panne le même jour.', '$P(\\text{panne}_1 \\cap \\text{panne}_2) = \\dfrac{1}{500}$', 'Pour des événements indépendants, la probabilité de leur intersection est le produit des probabilités.', ('Étape 1 : Les pannes des deux machines étant indépendantes, on utilise $P(\\text{panne}_1 \\cap \\text{panne}_2) = P(\\text{panne}_1)\\times P(\\text{panne}_2)$.', 'Étape 2 : $P(\\text{panne}_1 \\cap \\text{panne}_2) = \\dfrac{1}{20}\\times\\dfrac{1}{25} = \\dfrac{1}{500}$.')),
    (2033, "Notion d'indépendance", 1, "On lance deux dés équilibrés à $6$ faces, un rouge et un bleu, de façon indépendante. Calculer la probabilité d'obtenir un $6$ avec le dé rouge ET un $6$ avec le dé bleu.", '$P = \\dfrac{1}{36}$', 'Les deux lancers étant indépendants, multiplier les deux probabilités.', ('Étape 1 : $P(\\text{dé rouge}=6) = \\dfrac{1}{6}$ et $P(\\text{dé bleu}=6) = \\dfrac{1}{6}$, et les deux lancers sont indépendants.', 'Étape 2 : $P(\\text{dé rouge}=6 \\cap \\text{dé bleu}=6) = \\dfrac{1}{6}\\times\\dfrac{1}{6} = \\dfrac{1}{36}$.')),
    (2034, "Notion d'indépendance", 2, "Une entreprise étudie l'effet d'une publicité $A$ sur l'achat d'un produit $B$. Elle observe $P(B) = \\dfrac{3}{10}$ (probabilité d'achat en général) et $P_A(B) = \\dfrac{3}{10}$ (probabilité d'achat sachant que le client a vu la publicité). Comparer ces deux valeurs et conclure sur l'efficacité de la publicité.", "$P_A(B) = P(B)$ : la publicité n'a aucun effet mesurable sur la probabilité d'achat ($A$ et $B$ sont indépendants).", "Si $P_A(B) = P(B)$, voir la publicité ne change rien à la probabilité d'achat.", ('Étape 1 : $P_A(B) = \\dfrac{3}{10}$ et $P(B) = \\dfrac{3}{10}$ : les deux valeurs sont égales.', "Étape 2 : Cela signifie que $A$ et $B$ sont indépendants : le fait d'avoir vu la publicité ne modifie pas la probabilité d'achat.", 'Étape 3 : La publicité, dans cette étude, ne semble donc pas efficace pour augmenter les ventes.')),
    (2035, "Notion d'indépendance", 2, "Reprenons l'étude précédente avec de nouvelles données : $P(B) = \\dfrac{3}{10}$ et $P_A(B) = \\dfrac{1}{2}$. Comparer ces deux valeurs et conclure sur l'efficacité de la publicité.", "$P_A(B) = \\dfrac{1}{2} > P(B) = \\dfrac{3}{10}$ : la publicité augmente la probabilité d'achat, $A$ et $B$ ne sont pas indépendants.", "Comparer $P_A(B)$ à $P(B)$ : si $P_A(B) > P(B)$, l'événement $A$ favorise $B$.", ('Étape 1 : $P_A(B) = \\dfrac{1}{2} = \\dfrac{5}{10}$ et $P(B) = \\dfrac{3}{10}$.', 'Étape 2 : Comme $\\dfrac{5}{10} > \\dfrac{3}{10}$, on a $P_A(B) > P(B)$ : $A$ et $B$ ne sont pas indépendants.', "Étape 3 : Voir la publicité augmente la probabilité d'achat : la publicité a donc, cette fois, un effet mesurable et positif.")),
    (2036, "Notion d'indépendance", 4, "On considère deux couples d'événements. Couple 1 : $P(X) = \\dfrac{2}{5}$, $P(Y) = \\dfrac{1}{4}$, $P(X\\cap Y) = \\dfrac{1}{10}$. Couple 2 : $P(X') = \\dfrac{2}{5}$, $P(Y') = \\dfrac{1}{4}$, $P(X'\\cap Y') = \\dfrac{1}{5}$. 1) Déterminer si $X$ et $Y$ sont indépendants. 2) Déterminer si $X'$ et $Y'$ sont indépendants. 3) Expliquer pourquoi deux couples ayant les mêmes probabilités individuelles peuvent avoir des statuts d'indépendance différents.", "$X$ et $Y$ sont indépendants ($P(X\\cap Y) = P(X)P(Y) = \\dfrac{1}{10}$) ; $X'$ et $Y'$ ne le sont pas ($P(X'\\cap Y') = \\dfrac{1}{5} \\neq \\dfrac{1}{10}$).", "L'indépendance ne dépend pas seulement de $P(X)$ et $P(Y)$ mais de la valeur précise de $P(X\\cap Y)$.", ('Étape 1 : $P(X)\\times P(Y) = \\dfrac{2}{5}\\times\\dfrac{1}{4} = \\dfrac{1}{10}$.', 'Étape 2 : Pour le couple 1, $P(X\\cap Y) = \\dfrac{1}{10} = P(X)\\times P(Y)$ : $X$ et $Y$ sont indépendants.', "Étape 3 : Pour le couple 2, $P(X'\\cap Y') = \\dfrac{1}{5} = \\dfrac{2}{10} \\neq \\dfrac{1}{10}$ : $X'$ et $Y'$ ne sont pas indépendants.", "Étape 4 : L'indépendance dépend de la valeur exacte de l'intersection, pas seulement des probabilités individuelles : deux couples aux mêmes $P(X)$ et $P(Y)$ peuvent donc avoir des statuts d'indépendance opposés selon la valeur de $P(X\\cap Y)$.")),
    (2037, "Notion d'indépendance", 4, "Pour un contrat d'assurance habitation, on admet que l'événement $D$ « dégât des eaux dans l'année » et l'événement $V$ « vol dans l'année » sont indépendants, avec $P(D) = \\dfrac{1}{10}$ et $P(V) = \\dfrac{1}{20}$. 1) Calculer $P(D \\cap V)$. 2) En déduire $P(D \\cup V)$. 3) Calculer la probabilité qu'aucun des deux sinistres ne survienne dans l'année.", '$P(D\\cap V) = \\dfrac{1}{200}$, $P(D\\cup V) = \\dfrac{29}{200}$, $P(\\text{aucun sinistre}) = \\dfrac{171}{200}$', "Utiliser l'indépendance pour $P(D\\cap V)$, puis $P(D\\cup V)=P(D)+P(V)-P(D\\cap V)$, puis passer au complémentaire.", ('Étape 1 : $D$ et $V$ étant indépendants, $P(D\\cap V) = P(D)\\times P(V) = \\dfrac{1}{10}\\times\\dfrac{1}{20} = \\dfrac{1}{200}$.', 'Étape 2 : $P(D\\cup V) = P(D)+P(V)-P(D\\cap V) = \\dfrac{1}{10}+\\dfrac{1}{20}-\\dfrac{1}{200} = \\dfrac{29}{200}$.', 'Étape 3 : $P(\\text{aucun sinistre}) = 1 - P(D\\cup V) = 1 - \\dfrac{29}{200} = \\dfrac{171}{200}$.')),
    (2038, 'Arbres pondérés', 1, 'Un arbre pondéré à deux niveaux représente une expérience aléatoire : $P(A) = \\dfrac{3}{5}$ et, sur la branche issue de $A$, $P_A(B) = \\dfrac{1}{4}$. Calculer la probabilité $P(A \\cap B)$, associée au chemin $A$ puis $B$.', '$P(A\\cap B) = \\dfrac{3}{20}$', "Le long d'un chemin de l'arbre, on multiplie les probabilités rencontrées : $P(A\\cap B) = P(A)\\times P_A(B)$.", ("Étape 1 : La probabilité associée à un chemin de l'arbre est le produit des probabilités des branches parcourues.", 'Étape 2 : $P(A\\cap B) = P(A)\\times P_A(B) = \\dfrac{3}{5}\\times\\dfrac{1}{4} = \\dfrac{3}{20}$.')),
    (2039, 'Arbres pondérés', 2, 'Un arbre pondéré vérifie $P(A) = \\dfrac{1}{4}$ et $P_{\\overline{A}}(B) = \\dfrac{2}{5}$. Calculer la probabilité $P(\\overline{A} \\cap \\overline{B})$, associée au chemin $\\overline{A}$ puis $\\overline{B}$.', '$P(\\overline{A} \\cap \\overline{B}) = \\dfrac{9}{20}$', "Calculer d'abord $P(\\overline{A})$ et $P_{\\overline{A}}(\\overline{B}) = 1-P_{\\overline{A}}(B)$, puis multiplier.", ('Étape 1 : $P(\\overline{A}) = 1-\\dfrac{1}{4} = \\dfrac{3}{4}$.', 'Étape 2 : $P_{\\overline{A}}(\\overline{B}) = 1 - P_{\\overline{A}}(B) = 1-\\dfrac{2}{5} = \\dfrac{3}{5}$.', 'Étape 3 : $P(\\overline{A}\\cap\\overline{B}) = P(\\overline{A})\\times P_{\\overline{A}}(\\overline{B}) = \\dfrac{3}{4}\\times\\dfrac{3}{5} = \\dfrac{9}{20}$.')),
    (2040, 'Arbres pondérés', 4, "Une urne contient $5$ boules rouges et $3$ boules vertes. On tire successivement et sans remise deux boules. Construire l'arbre pondéré de cette expérience à deux niveaux, puis calculer la probabilité que la seconde boule tirée soit rouge.", '$P(\\text{2e rouge}) = \\dfrac{5}{8}$', 'Il y a deux chemins menant à « 2e boule rouge » : Rouge puis Rouge, ou Verte puis Rouge. Ne pas oublier que le tirage est sans remise : les probabilités du second niveau changent selon la première boule tirée.', ('Étape 1 : Premier niveau : $P(R_1) = \\dfrac{5}{8}$ et $P(V_1) = \\dfrac{3}{8}$.', 'Étape 2 : Sans remise, si $R_1$ est réalisé il reste $4$ rouges sur $7$ boules : $P_{R_1}(R_2) = \\dfrac{4}{7}$. Si $V_1$ est réalisé, il reste $5$ rouges sur $7$ : $P_{V_1}(R_2) = \\dfrac{5}{7}$.', 'Étape 3 : $P(R_1\\cap R_2) = \\dfrac{5}{8}\\times\\dfrac{4}{7} = \\dfrac{5}{14}$ et $P(V_1\\cap R_2) = \\dfrac{3}{8}\\times\\dfrac{5}{7} = \\dfrac{15}{56}$.', "Étape 4 : D'après la formule des probabilités totales, $P(R_2) = P(R_1\\cap R_2) + P(V_1\\cap R_2) = \\dfrac{5}{14} + \\dfrac{15}{56} = \\dfrac{5}{8}$.")),
    (2041, 'Arbres pondérés', 4, "Une urne contient $4$ boules rouges et $6$ boules vertes. On tire successivement et sans remise deux boules. Construire l'arbre pondéré, puis calculer la probabilité que la seconde boule tirée soit rouge.", '$P(\\text{2e rouge}) = \\dfrac{2}{5}$', 'Additionner les probabilités des deux chemins menant à « 2e boule rouge », en tenant compte du tirage sans remise.', ('Étape 1 : Premier niveau : $P(R_1) = \\dfrac{4}{10} = \\dfrac{2}{5}$ et $P(V_1) = \\dfrac{6}{10} = \\dfrac{3}{5}$.', 'Étape 2 : Sans remise : $P_{R_1}(R_2) = \\dfrac{3}{9} = \\dfrac{1}{3}$ et $P_{V_1}(R_2) = \\dfrac{4}{9}$.', 'Étape 3 : $P(R_1\\cap R_2) = \\dfrac{4}{10}\\times\\dfrac{3}{9} = \\dfrac{2}{15}$ et $P(V_1\\cap R_2) = \\dfrac{6}{10}\\times\\dfrac{4}{9} = \\dfrac{4}{15}$.', 'Étape 4 : $P(R_2) = \\dfrac{2}{15} + \\dfrac{4}{15} = \\dfrac{2}{5}$.')),
    (2042, 'Arbres pondérés', 3, "Dans une population, $P(M) = \\dfrac{1}{50}$ (proportion de malades). Un test donne $P_M(T) = \\dfrac{19}{20}$ (test positif si malade) et $P_{\\overline{M}}(T) = \\dfrac{1}{25}$ (faux positif). L'arbre pondéré donne $P(T) = \\dfrac{291}{5000}$. Interpréter cette probabilité $P(T)$ dans le contexte de l'énoncé.", "$P(T) = \\dfrac{291}{5000}$ signifie qu'environ 5.8\\% de la population totale sera testée positive, malades et faux positifs confondus.", "$P(T)$ regroupe deux chemins de l'arbre : « malade et testé positif » et « non malade mais testé positif ».", ("Étape 1 : $P(T)$ est la probabilité, calculée sur toute la population, qu'une personne prise au hasard soit testée positive, que ce soit à raison (vrai positif) ou à tort (faux positif).", "Étape 2 : $P(T) = \\dfrac{291}{5000}$ signifie qu'environ 5.8\\% de la population sera testée positive.", 'Étape 3 : Cette proportion est bien plus grande que $P(M) = \\dfrac{1}{50} = 2\\%$ : la plupart des personnes testées positives ne sont donc pas malades, en raison du taux de faux positifs.')),
    (2043, 'Arbres pondérés', 3, "Dans l'exercice de l'urne à $5$ boules rouges et $3$ boules vertes tirées successivement sans remise, on a trouvé $P(\\text{2e rouge}) = \\dfrac{5}{8}$, exactement la même valeur que $P(\\text{1re rouge})$. Expliquer, sans reprendre le calcul, pourquoi ce résultat est cohérent.", "Par symétrie : avant tout tirage, chaque boule (et donc chaque rang) a la même chance d'être rouge, tirer une boule en premier ou en second ne change pas ses chances d'être rouge.", "Penser à la position des boules dans l'urne avant tout tirage : rien ne distingue le premier tirage du second a priori.", ('Étape 1 : Avant de commencer les tirages, les $8$ boules sont interchangeables : rien ne distingue la position « tirée en premier » de la position « tirée en seconde ».', "Étape 2 : Chaque boule a donc la même probabilité d'être rouge, qu'elle soit tirée au premier ou au second tirage.", "Étape 3 : C'est pourquoi $P(\\text{2e rouge}) = P(\\text{1re rouge}) = \\dfrac{5}{8}$, bien que le calcul passe par deux chemins différents dans l'arbre.")),
    (2044, 'Arbres pondérés', 3, "Dans un lycée, $30\\%$ des élèves sont inscrits en option musique. Parmi les élèves inscrits en option musique, la moitié pratique un instrument à cordes. Parmi les élèves non inscrits en option musique, $\\dfrac{1}{5}$ pratique tout de même un instrument à cordes en dehors du lycée. Quelle est la probabilité qu'un élève choisi au hasard pratique un instrument à cordes ?", '$P(\\text{cordes}) = \\dfrac{29}{100}$', "Traduire l'énoncé par un arbre pondéré à deux niveaux (option musique ou non, puis instrument à cordes ou non), puis appliquer la formule des probabilités totales.", ("Étape 1 : On note $M$ « l'élève est en option musique » et $C$ « l'élève pratique un instrument à cordes ». On a $P(M) = \\dfrac{3}{10}$, $P_M(C) = \\dfrac{1}{2}$ et $P_{\\overline{M}}(C) = \\dfrac{1}{5}$.", 'Étape 2 : $P(\\overline{M}) = 1-\\dfrac{3}{10} = \\dfrac{7}{10}$.', 'Étape 3 : $P(C) = P(M)\\times P_M(C) + P(\\overline{M})\\times P_{\\overline{M}}(C) = \\dfrac{3}{10}\\times\\dfrac{1}{2} + \\dfrac{7}{10}\\times\\dfrac{1}{5} = \\dfrac{29}{100}$.')),
    (2045, 'Arbres pondérés', 3, "Une entreprise de livraison reçoit $80\\%$ de ses commandes via internet, le reste par téléphone. Une commande passée via internet a $10\\%$ de chances d'être livrée en retard ; une commande passée par téléphone a $25\\%$ de chances d'être en retard. Quelle est la probabilité qu'une commande prise au hasard soit livrée en retard ?", '$P(\\text{retard}) = \\dfrac{13}{100}$', "Traduire l'énoncé par un arbre : internet ou téléphone, puis retard ou non, avant d'utiliser la formule des probabilités totales.", ('Étape 1 : On note $I$ « commande via internet » et $R$ « livraison en retard ». $P(I) = \\dfrac{4}{5}$, $P_I(R) = \\dfrac{1}{10}$, $P_{\\overline{I}}(R) = \\dfrac{1}{4}$.', 'Étape 2 : $P(\\overline{I}) = 1-\\dfrac{4}{5} = \\dfrac{1}{5}$.', 'Étape 3 : $P(R) = \\dfrac{4}{5}\\times\\dfrac{1}{10} + \\dfrac{1}{5}\\times\\dfrac{1}{4} = \\dfrac{13}{100}$.')),
    (2046, 'Arbres pondérés', 2, "Sur un arbre pondéré, une branche issue du nœud $A$ porte la probabilité $P_A(B) = \\dfrac{7}{20}$ et l'autre branche issue de $A$ porte la probabilité $\\dfrac{3}{4}$. Vrai ou faux : « cet arbre est correctement pondéré. » Justifier.", "Faux : les deux probabilités issues d'un même nœud doivent sommer à $1$, or $\\dfrac{7}{20}+\\dfrac{3}{4} = \\dfrac{11}{10} \\neq 1$.", "Sur un arbre pondéré, la somme des probabilités des branches issues d'un même nœud doit toujours valoir $1$.", ('Étape 1 : Les deux branches issues de $A$ correspondent aux événements complémentaires $B$ et $\\overline{B}$ (sachant $A$) : leurs probabilités doivent sommer à $1$.', 'Étape 2 : $\\dfrac{7}{20} + \\dfrac{3}{4} = \\dfrac{7}{20} + \\dfrac{15}{20} = \\dfrac{22}{20} = \\dfrac{11}{10} \\neq 1$.', "Étape 3 : La somme dépasse $1$, ce qui est impossible pour deux branches complémentaires : l'arbre proposé est donc incorrect. L'affirmation est fausse.")),
    (2047, 'Arbres pondérés', 2, 'Sur un arbre, on a $P(A) = \\dfrac{1}{2}$, $P_A(B) = \\dfrac{2}{5}$, $P(\\overline{A}) = \\dfrac{1}{2}$ et $P_{\\overline{A}}(B) = \\dfrac{2}{5}$. Vrai ou faux : « les chemins « $A$ puis $B$ » et « $\\overline{A}$ puis $B$ » ont la même probabilité. » Justifier.', 'Vrai, les deux chemins ont la même probabilité $\\dfrac{1}{5}$.', 'Calculer $P(A\\cap B)$ et $P(\\overline{A}\\cap B)$ séparément puis comparer.', ('Étape 1 : $P(A\\cap B) = P(A)\\times P_A(B) = \\dfrac{1}{2}\\times\\dfrac{2}{5} = \\dfrac{1}{5}$.', 'Étape 2 : $P(\\overline{A}\\cap B) = P(\\overline{A})\\times P_{\\overline{A}}(B) = \\dfrac{1}{2}\\times\\dfrac{2}{5} = \\dfrac{1}{5}$.', "Étape 3 : Les deux chemins donnent bien la même probabilité $\\dfrac{1}{5}$ : ceci vient du fait que $P(A) = P(\\overline{A})$ et $P_A(B) = P_{\\overline{A}}(B)$ ici. L'affirmation est vraie.")),
    (2048, 'Arbres pondérés', 2, 'Sur un arbre pondéré, $P(A) = \\dfrac{2}{5}$ et $P_A(B) = \\dfrac{3}{10}$. Un élève calcule la probabilité du chemin « $A$ puis $B$ » ainsi : « $P(A\\cap B) = P(A) + P_A(B) = \\dfrac{2}{5}+\\dfrac{3}{10} = \\dfrac{7}{10}$ ». Identifier son erreur et donner le calcul correct.', "$P(A\\cap B) = \\dfrac{3}{25}$ : le long d'un chemin de l'arbre, on multiplie les probabilités, on ne les additionne pas.", "La règle du produit le long des branches d'un arbre : $P(A\\cap B) = P(A)\\times P_A(B)$.", ("Étape 1 : L'élève a additionné les probabilités des deux branches successives au lieu de les multiplier.", "Étape 2 : La règle correcte pour un chemin de l'arbre est $P(A\\cap B) = P(A)\\times P_A(B) = \\dfrac{2}{5}\\times\\dfrac{3}{10} = \\dfrac{3}{25}$.", "Étape 3 : Le résultat correct $\\dfrac{3}{25} = 0,12$ est bien inférieur à $\\dfrac{7}{10} = 0,7$ obtenu par erreur : une probabilité d'intersection doit toujours être inférieure ou égale à chacune des probabilités qui la composent.")),
    (2049, 'Arbres pondérés', 3, 'Une urne contient $3$ boules blanches et $2$ boules noires. On tire deux boules successivement sans remise. Pour calculer $P(\\text{2 blanches})$, un élève écrit : « $P(\\text{2 blanches}) = \\dfrac{3}{5}\\times\\dfrac{3}{5} = \\dfrac{9}{25}$ » en gardant la même probabilité $\\dfrac{3}{5}$ pour les deux tirages. Identifier son erreur et donner le calcul correct.', '$P(\\text{2 blanches}) = \\dfrac{3}{10}$ : au second tirage, il ne reste que $2$ blanches parmi $4$ boules (tirage sans remise), pas $3$ sur $5$.', "Sans remise, la composition de l'urne change après le premier tirage : la probabilité de la seconde branche doit être recalculée.", ("Étape 1 : L'élève applique à tort la même probabilité $\\dfrac{3}{5}$ aux deux tirages, comme s'il y avait remise, alors que l'énoncé précise « sans remise ».", 'Étape 2 : Au premier tirage, $P(\\text{1re blanche}) = \\dfrac{3}{5}$. Après ce tirage, il reste $2$ blanches parmi $4$ boules : $P_{\\text{1re blanche}}(\\text{2e blanche}) = \\dfrac{2}{4} = \\dfrac{1}{2}$.', 'Étape 3 : $P(\\text{2 blanches}) = \\dfrac{3}{5}\\times\\dfrac{1}{2} = \\dfrac{3}{10}$, différent du résultat erroné $\\dfrac{9}{25}$.')),
    (2050, 'Arbres pondérés', 3, "Une étude épidémiologique indique que $30\\%$ d'une population est fumeuse. La probabilité de développer un cancer du poumon est $\\dfrac{1}{20}$ chez les fumeurs et $\\dfrac{1}{200}$ chez les non-fumeurs. Construire l'arbre pondéré, puis calculer la probabilité qu'une personne prise au hasard développe ce cancer.", '$P(\\text{cancer}) = \\dfrac{37}{2000}$', "Construire l'arbre : fumeur ou non, puis cancer ou non ; appliquer la formule des probabilités totales.", ('Étape 1 : $P(F) = \\dfrac{3}{10}$, $P(\\overline{F}) = \\dfrac{7}{10}$, $P_F(C) = \\dfrac{1}{20}$, $P_{\\overline{F}}(C) = \\dfrac{1}{200}$.', 'Étape 2 : $P(C) = P(F)\\times P_F(C) + P(\\overline{F})\\times P_{\\overline{F}}(C) = \\dfrac{3}{10}\\times\\dfrac{1}{20} + \\dfrac{7}{10}\\times\\dfrac{1}{200} = \\dfrac{37}{2000}$.')),
    (2051, 'Arbres pondérés', 3, "Une entreprise s'approvisionne auprès de deux fournisseurs : $60\\%$ des pièces viennent du fournisseur $X$, $40\\%$ du fournisseur $Y$. Le taux de pièces défectueuses est $\\dfrac{1}{25}$ pour $X$ et $\\dfrac{1}{10}$ pour $Y$. Construire l'arbre pondéré, puis calculer la probabilité qu'une pièce prise au hasard dans le stock soit défectueuse.", '$P(\\text{défectueuse}) = \\dfrac{8}{125}$', "Construire l'arbre : fournisseur $X$ ou $Y$, puis défectueuse ou non ; appliquer la formule des probabilités totales.", ('Étape 1 : $P(X) = \\dfrac{3}{5}$, $P(Y) = \\dfrac{2}{5}$, $P_X(D) = \\dfrac{1}{25}$, $P_Y(D) = \\dfrac{1}{10}$.', 'Étape 2 : $P(D) = P(X)\\times P_X(D) + P(Y)\\times P_Y(D) = \\dfrac{3}{5}\\times\\dfrac{1}{25} + \\dfrac{2}{5}\\times\\dfrac{1}{10} = \\dfrac{8}{125}$.')),
    (2052, 'Arbres pondérés', 4, "Dans le contexte de l'exercice précédent (fournisseurs $X$ et $Y$), comparer $P(X\\cap D)$ et $P(Y\\cap D)$ pour déterminer quel fournisseur est à l'origine de la plus grande proportion de pièces défectueuses dans le stock total.", "$P(X\\cap D) = \\dfrac{3}{125}$ et $P(Y\\cap D) = \\dfrac{1}{25}$ ; comme $\\dfrac{1}{25} > \\dfrac{3}{125}$, le fournisseur $Y$ est à l'origine de la plus grande proportion de pièces défectueuses, bien qu'il livre moins de pièces.", "Calculer les deux probabilités de chemin de l'arbre puis comparer leurs valeurs (mise au même dénominateur si besoin).", ('Étape 1 : $P(X\\cap D) = P(X)\\times P_X(D) = \\dfrac{3}{5}\\times\\dfrac{1}{25} = \\dfrac{3}{125}$.', 'Étape 2 : $P(Y\\cap D) = P(Y)\\times P_Y(D) = \\dfrac{2}{5}\\times\\dfrac{1}{10} = \\dfrac{1}{25}$.', 'Étape 3 : En réduisant au même dénominateur $125$ : $P(X\\cap D) = \\dfrac{3}{125}$ et $P(Y\\cap D) = \\dfrac{5}{125}$. Comme $\\dfrac{5}{125} > \\dfrac{3}{125}$, le fournisseur $Y$, bien que livrant moins de pièces, contribue davantage aux pièces défectueuses car son taux de défaut est plus élevé.')),
    (2053, 'Arbres pondérés', 5, "Un jeu propose un tirage dans une boîte contenant $2$ jetons gagnants sur $10$. Après chaque tirage, le jeton est remis dans la boîte. Un joueur effectue deux tirages indépendants. 1) Construire l'arbre pondéré à deux niveaux. 2) Calculer la probabilité de gagner exactement une fois sur les deux tirages. 3) Calculer la probabilité de ne gagner aucune fois, et interpréter ce résultat en termes de fréquence attendue sur $100$ joueurs.", '$P(\\text{exactement 1 gain}) = \\dfrac{8}{25}$ ; $P(\\text{0 gain}) = \\dfrac{16}{25}$, soit environ 64 joueurs sur $100$ qui ne gagnent jamais.', 'Les deux tirages étant indépendants et identiques, il y a deux chemins menant à « exactement un gain » : Gagne-Perd et Perd-Gagne.', ('Étape 1 : À chaque tirage, $P(\\text{gagne}) = \\dfrac{2}{10} = \\dfrac{1}{5}$ et $P(\\text{perd}) = \\dfrac{4}{5}$, et les deux tirages sont indépendants (remise).', 'Étape 2 : $P(\\text{exactement 1 gain}) = P(\\text{G,P}) + P(\\text{P,G}) = 2\\times\\dfrac{1}{5}\\times\\dfrac{4}{5} = \\dfrac{8}{25}$.', 'Étape 3 : $P(\\text{0 gain}) = P(\\text{P,P}) = \\dfrac{4}{5}\\times\\dfrac{4}{5} = \\dfrac{16}{25}$.', "Étape 4 : Sur $100$ joueurs, on peut donc s'attendre à ce qu'environ $\\dfrac{16}{25}\\times 100 = 64$ d'entre eux ne gagnent jamais lors de leurs deux tirages.")),
    (2054, 'Arbres pondérés', 5, "Une urne contient $4$ boules rouges et $2$ boules noires. On tire successivement et sans remise deux boules. 1) Construire l'arbre pondéré. 2) Calculer la probabilité de tirer deux boules rouges. 3) Calculer la probabilité de tirer deux boules noires. 4) Comparer ces deux probabilités et expliquer pourquoi elles sont très différentes.", '$P(\\text{2 rouges}) = \\dfrac{2}{5}$ et $P(\\text{2 noires}) = \\dfrac{1}{15}$ ; la première est bien plus grande car il y a davantage de boules rouges au départ.', "Utiliser à chaque niveau la composition restante de l'urne (tirage sans remise), puis comparer les deux probabilités obtenues.", ('Étape 1 : Premier niveau : $P(R_1) = \\dfrac{4}{6} = \\dfrac{2}{3}$ et $P(N_1) = \\dfrac{2}{6} = \\dfrac{1}{3}$.', 'Étape 2 : $P_{R_1}(R_2) = \\dfrac{3}{5}$, donc $P(\\text{2 rouges}) = \\dfrac{2}{3}\\times\\dfrac{3}{5} = \\dfrac{2}{5}$.', 'Étape 3 : $P_{N_1}(N_2) = \\dfrac{1}{5}$, donc $P(\\text{2 noires}) = \\dfrac{1}{3}\\times\\dfrac{1}{5} = \\dfrac{1}{15}$.', "Étape 4 : $\\dfrac{2}{5} > \\dfrac{1}{15}$ : cela s'explique par le fait qu'il y a deux fois plus de boules rouges que de boules noires au départ, ce qui rend un double tirage rouge nettement plus probable.")),
    (2055, 'Arbres pondérés', 5, "Une compagnie d'assurance auto constate que $25\\%$ de ses assurés ont moins de $25$ ans (« jeunes conducteurs »). La probabilité qu'un jeune conducteur ait un sinistre dans l'année est $\\dfrac{3}{10}$, contre $\\dfrac{1}{10}$ pour les autres conducteurs. 1) Construire l'arbre pondéré et calculer $P(\\text{sinistre})$. 2) Calculer la probabilité qu'un assuré ayant eu un sinistre soit un jeune conducteur. 3) Comparer ce résultat à la proportion initiale de jeunes conducteurs ($25\\%$) et conclure sur le lien entre âge et sinistralité.", '$P(\\text{sinistre}) = \\dfrac{3}{20}$, $P_{\\text{sinistre}}(\\text{jeune}) = \\dfrac{1}{2}$ ; comme $\\dfrac{1}{2} > \\dfrac{1}{4}$, les jeunes conducteurs sont surreprésentés parmi les sinistrés.', 'Calculer $P(\\text{sinistre})$ avec la formule des probabilités totales, puis $P_{\\text{sinistre}}(\\text{jeune})$ avec la formule de Bayes, et comparer à $P(\\text{jeune}) = \\dfrac{1}{4}$.', ('Étape 1 : $P(\\text{non jeune}) = 1-\\dfrac{1}{4} = \\dfrac{3}{4}$.', 'Étape 2 : $P(\\text{sinistre}) = \\dfrac{1}{4}\\times\\dfrac{3}{10} + \\dfrac{3}{4}\\times\\dfrac{1}{10} = \\dfrac{3}{20}$.', 'Étape 3 : $P(\\text{jeune}\\cap\\text{sinistre}) = \\dfrac{1}{4}\\times\\dfrac{3}{10} = \\dfrac{3}{40}$, donc $P_{\\text{sinistre}}(\\text{jeune}) = \\dfrac{\\dfrac{3}{40}}{\\dfrac{3}{20}} = \\dfrac{1}{2}$.', "Étape 4 : Comme $P_{\\text{sinistre}}(\\text{jeune}) = \\dfrac{1}{2} = 0,5 > P(\\text{jeune}) = 0,25$, un assuré sinistré a deux fois plus de chances d'être un jeune conducteur qu'un assuré pris au hasard : l'âge et la sinistralité sont donc liés dans cette population.")),
)
